-- Initial schema from backend/database/World Cup Analytics Platform.sql.
-- Preserve the reviewed ERD; dataset import is a separate step.

CREATE TABLE "tournaments" (
  "tournament_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "tournament_name" varchar(100) NOT NULL,
  "year" int UNIQUE NOT NULL,
  "host_country" varchar(100),
  "start_date" date,
  "end_date" date
);

CREATE TABLE "teams" (
  "team_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "team_name" varchar(100) NOT NULL,
  "fifa_code" varchar(3) UNIQUE NOT NULL,
  "confederation" varchar(20)
);

CREATE TABLE "tournament_teams" (
  "tournament_team_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "tournament_id" bigint NOT NULL,
  "team_id" bigint NOT NULL,
  "group_letter" varchar(5),
  "fifa_ranking_pre_tournament" int,
  "elo_rating_pre_tournament" int,
  "manager_name" varchar(100)
);

CREATE TABLE "players" (
  "player_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "team_id" bigint NOT NULL,
  "player_name" varchar(150) NOT NULL,
  "position" varchar(30),
  "date_of_birth" date,
  "height_cm" int
);

CREATE TABLE "tournament_squads" (
  "tournament_squad_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "tournament_id" bigint NOT NULL,
  "player_id" bigint NOT NULL,
  "shirt_number" int,
  "club_team" varchar(150),
  "caps_before_tournament" int,
  "international_goals_before_tournament" int,
  "market_value_eur" bigint
);

CREATE TABLE "tournament_stages" (
  "stage_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "tournament_id" bigint NOT NULL,
  "stage_name" varchar(50) NOT NULL,
  "stage_order" int,
  "is_knockout" boolean NOT NULL DEFAULT false
);

CREATE TABLE "venues" (
  "venue_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "stadium_name" varchar(150) NOT NULL,
  "city" varchar(100),
  "country" varchar(100),
  "capacity" int,
  "latitude" decimal(9,6),
  "longitude" decimal(9,6)
);

CREATE TABLE "matches" (
  "match_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "tournament_id" bigint NOT NULL,
  "stage_id" bigint NOT NULL,
  "venue_id" bigint,
  "home_team_id" bigint NOT NULL,
  "away_team_id" bigint NOT NULL,
  "match_date" date NOT NULL,
  "kickoff_time_utc" time,
  "home_score" int,
  "away_score" int,
  "home_xg" decimal(5,2),
  "away_xg" decimal(5,2),
  "status" varchar(30)
);

CREATE TABLE "match_team_stats" (
  "match_team_stat_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "match_id" bigint NOT NULL,
  "team_id" bigint NOT NULL,
  "possession_pct" decimal(5,2),
  "total_shots" int,
  "shots_on_target" int,
  "corners" int,
  "fouls" int,
  "offsides" int
);

CREATE TABLE "match_events" (
  "event_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "match_id" bigint NOT NULL,
  "team_id" bigint,
  "player_id" bigint,
  "minute" int NOT NULL,
  "event_type" varchar(50) NOT NULL
);

CREATE UNIQUE INDEX ON "tournament_teams" ("tournament_id", "team_id");

CREATE UNIQUE INDEX ON "tournament_squads" ("tournament_id", "player_id");

CREATE UNIQUE INDEX ON "match_team_stats" ("match_id", "team_id");

ALTER TABLE "tournament_teams" ADD FOREIGN KEY ("tournament_id") REFERENCES "tournaments" ("tournament_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "tournament_teams" ADD FOREIGN KEY ("team_id") REFERENCES "teams" ("team_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "players" ADD FOREIGN KEY ("team_id") REFERENCES "teams" ("team_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "tournament_squads" ADD FOREIGN KEY ("tournament_id") REFERENCES "tournaments" ("tournament_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "tournament_squads" ADD FOREIGN KEY ("player_id") REFERENCES "players" ("player_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "tournament_stages" ADD FOREIGN KEY ("tournament_id") REFERENCES "tournaments" ("tournament_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "matches" ADD FOREIGN KEY ("tournament_id") REFERENCES "tournaments" ("tournament_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "matches" ADD FOREIGN KEY ("stage_id") REFERENCES "tournament_stages" ("stage_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "matches" ADD FOREIGN KEY ("venue_id") REFERENCES "venues" ("venue_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "matches" ADD FOREIGN KEY ("home_team_id") REFERENCES "teams" ("team_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "matches" ADD FOREIGN KEY ("away_team_id") REFERENCES "teams" ("team_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "match_team_stats" ADD FOREIGN KEY ("match_id") REFERENCES "matches" ("match_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "match_team_stats" ADD FOREIGN KEY ("team_id") REFERENCES "teams" ("team_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "match_events" ADD FOREIGN KEY ("match_id") REFERENCES "matches" ("match_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "match_events" ADD FOREIGN KEY ("team_id") REFERENCES "teams" ("team_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "match_events" ADD FOREIGN KEY ("player_id") REFERENCES "players" ("player_id") DEFERRABLE INITIALLY IMMEDIATE;
